def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([5]), fmt([0, 0]), fmt([0, 1]), fmt([1, 0]), fmt([3, 3, 3]), fmt([7, 7, 3]),
             fmt([3, 7, 7]), fmt([10**9, 0, 10**9]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1])]
    for n in (2, 3, 4, 6, 8, 10, 15, 30):
        for _ in range(3):
            tests.append(fmt([rng.randint(0, rng.choice([2, 5, 100])) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(N)]))
    tests.append(fmt([10**9] * N))
    tests.append(fmt([10**9] * (N - 1) + [0]))
    tests.append(fmt(list(range(N))))
    return tests

